#!/usr/bin/env python3
# SPDX-License-Identifier: AGPL-3.0-only
"""Rebuild the compact CC0 acoustic bank. Requires Python 3 and ffmpeg.
This generates independent Linn-inspired material, never Linn ROM data.
"""
from pathlib import Path
import array, hashlib, json, math, subprocess
ROOT = Path(__file__).resolve().parent
RATE = 35000
# lane, original filename, maximum capture duration, independent recordist URL
FILES = [
 ('kick','drum_heavy_kick.flac',.40,'https://freesound.org/people/Zajo/sounds/4832/'),
 ('snare','drum_snare_hard.flac',.55,'https://freesound.org/people/menegass/sounds/100058/'),
 ('tom_low','drum_tom_lo_hard.flac',.75,'https://freesound.org/people/menegass/sounds/100064/'),
 ('tom_mid','drum_tom_mid_hard.flac',.65,'https://freesound.org/people/menegass/sounds/100066/'),
 ('tom_high','drum_tom_hi_hard.flac',.55,'https://freesound.org/people/menegass/sounds/100062/'),
 ('rim','rim.wav',.30,'https://github.com/sgossner/VCSL'),
 ('clap','clap.wav',.65,'https://github.com/sgossner/VCSL'),
 ('hat_closed','drum_cymbal_closed.flac',.22,'https://freesound.org/people/menegass/sounds/100053/'),
 ('hat_open','drum_cymbal_open.flac',.9,'https://freesound.org/people/menegass/sounds/100055/'),
 ('crash','drum_splash_hard.flac',2.5,'https://freesound.org/people/menegass/sounds/100060/'),
 ('ride','drum_cymbal_soft.flac',1.2,'https://freesound.org/people/menegass/sounds/100057/'),
]
lines=['// Generated by generate.py. Sample data: CC0-1.0; see PROVENANCE.md.',
       '// Analytic mu=255 companding; NOT the AM6070 segmented bit format.',
       '#pragma once','#include <cstdint>','namespace ag::linn_pcm {',
       'inline constexpr double rate = 35000;']
manifest=[]
for name, filename, cap, url in FILES:
 p=ROOT/'sources'/filename
 raw=subprocess.check_output(['ffmpeg','-v','error','-i',str(p),'-ac','1','-af','highpass=f=25','-ar',str(RATE),'-f','f32le','-'])
 samples=array.array('f');samples.frombytes(raw)
 peak=max(abs(x) for x in samples)
 assert peak>0
 start=max(0,next(i for i,x in enumerate(samples) if abs(x)>.012*peak)-8)
 x=list(samples[start:start+round(cap*RATE)])
 # Keep original waveform/envelope; remove excess quiet tail, then 8ms fade.
 last=max(i for i,v in enumerate(x) if abs(v)>.0005*peak)
 x=x[:min(len(x),last+round(.008*RATE))]
 gain=.9/max(abs(v) for v in x)
 codes=[]
 for i,v in enumerate(x):
  fade=min(1.,(len(x)-1-i)/(.008*RATE))
  v=max(-1.,min(1.,v*gain*fade))
  mag=round(127*math.log1p(255*abs(v))/math.log(256))
  codes.append(mag+(128 if v<0 else 0))
 lines.append(f'inline constexpr std::uint8_t {name}[] = {{')
 for i in range(0,len(codes),32): lines.append(','.join(map(str,codes[i:i+32]))+',')
 lines.append('};')
 manifest.append(dict(lane=name,file=filename,sha256=hashlib.sha256(p.read_bytes()).hexdigest(),recordist_url=url,rate=RATE,frames=len(codes),trim_start_frames=start,normalized_peak=.9,processing='mono; 25Hz highpass; FFmpeg resample to35000Hz; onset trim; peak normalize; maximum duration trim; 8ms tail fade; analytic mu255 signed-magnitude8bit companding'))
lines += ['struct Sample { const std::uint8_t* data; int frames; };','inline constexpr Sample bank[] = {']
for name,*_ in FILES: lines.append(f'{{{name}, int(sizeof({name}))}},')
lines += ['};','}']
(ROOT/'PcmData.h').write_text('\n'.join(lines)+'\n')
(ROOT/'manifest.json').write_text(json.dumps(manifest,indent=2)+'\n')
print('Generated',sum(x['frames'] for x in manifest),'bytes of sample data')
